import itertools

def is_colorful_fast(m, n):
    w = n + 1
    # Try all possible sequences using itertools.product
    # This is still n^m. Let's use backtracking with better pruning.
    seq = [None] * m

    def solve(pos):
        if pos == m:
            for j in range(m):
                window = set(seq[(j + k) % m] for k in range(w))
                if len(window) < n:
                    return False
            return True

        for flavor in range(n):
            seq[pos] = flavor
            # Pruning: any window of size w that is now fully determined must be valid.
            # The window ending at pos: seq[pos-w+1 ... pos]
            if pos >= w - 1:
                # Window is from pos-w+1 to pos.
                # But we also need to check wrap-around windows eventually.
                # For now, just check the window that just got completed.
                window = set(seq[pos-w+1 : pos+1])
                if len(window) < n:
                    continue
            if solve(pos + 1):
                return True
        return False

    return solve(0)

for m in range(4, 20):
    print(f"n=3, m={m}: {is_colorful_fast(m, 3)}")

