import itertools

def check_colorful(m, n):
    w = n + 1
    for seq in itertools.product(range(n), repeat=m):
        is_ok = True
        for j in range(m):
            window = set(seq[(j + k) % m] for k in range(w))
            if len(window) < n:
                is_ok = False
                break
        if is_ok:
            return True
    return False

print(f"n=4, m=11: {check_colorful(11, 4)}")

